#include <array>
#include <cstddef>
#include <vector>
#include <algorithm>
#include <omp.h>

void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    bins.fill(0);

    #pragma omp parallel
    {
        std::array<size_t, 10> local{};
        local.fill(0);

        #pragma omp for nowait
        for (std::size_t i = 0; i < x.size(); ++i) {
            // x is in [0,100] inclusive; map 100 -> last bin (90-100]
            int b = static_cast<int>(x[i] / 10.0);
            if (b < 0) b = 0;
            if (b > 9) b = 9;
            ++local[static_cast<std::size_t>(b)];
        }

        #pragma omp critical
        {
            for (std::size_t k = 0; k < 10; ++k) {
                bins[k] += local[k];
            }
        }
    }
}
